const std = @import("std");

pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});

    const mod = b.createModule(.{
        .root_source_file = b.path("src/main.zig"),
        .target = target,
        .optimize = optimize,
    });

    const exe = b.addExecutable(.{ .name = "kvhttp", .root_module = mod });
    b.installArtifact(exe);

    const run = b.addRunArtifact(exe);
    if (b.args) |args| run.addArgs(args);
    b.step("run", "Run the server").dependOn(&run.step);

    const tests = b.addTest(.{ .root_module = mod });
    b.step("test", "Run unit tests").dependOn(&b.addRunArtifact(tests).step);
}

//! Accept loop and per-connection request handling.
//!
//! Each connection runs as its own concurrent task and serves exactly one
//! request. Reads are bounded by an idle timeout so that stalled clients
//! cannot pin a task forever.
const Server = @This();

const std = @import("std");
const Io = std.Io;
const net = Io.net;
const posix = std.posix;
const Allocator = std.mem.Allocator;

const Store = @import("Store.zig");
const http = @import("http.zig");

const log = std.log.scoped(.server);

pub const max_head_bytes = 16 * 1024;
pub const max_key_len = 64;
pub const max_value_bytes = 1 << 20;
/// Idle timeout for each read from a client.
const read_timeout_ms = 10_000;
/// Upper bound on what is drained from a client after replying.
const drain_limit = 4 * 1024 * 1024;

io: Io,
gpa: Allocator,
store: *Store,

/// Accepts connections forever, serving each one concurrently. Returns only
/// on an unrecoverable accept error.
pub fn run(s: *Server, listener: *net.Server) !void {
    var group: Io.Group = .init;
    defer group.cancel(s.io);

    while (true) {
        const stream = listener.accept(s.io) catch |err| switch (err) {
            error.ConnectionAborted, error.ProtocolFailure, error.BlockedByFirewall, error.WouldBlock => continue,
            error.ProcessFdQuotaExceeded, error.SystemFdQuotaExceeded, error.SystemResources => {
                // Resource pressure: back off briefly and let connections drain.
                try s.io.sleep(.fromMilliseconds(10), .awake);
                continue;
            },
            else => |e| return e,
        };
        configureClient(stream);

        group.concurrent(s.io, handleConnection, .{ s, stream }) catch {
            var conn: Connection = undefined;
            conn.init(s, stream);
            conn.respond(.{ .status = .service_unavailable }) catch {};
            stream.close(s.io);
        };
    }
}

fn configureClient(stream: net.Stream) void {
    const one = std.mem.toBytes(@as(c_int, 1));
    posix.setsockopt(stream.socket.handle, posix.IPPROTO.TCP, posix.TCP.NODELAY, &one) catch {};
}

fn handleConnection(s: *Server, stream: net.Stream) void {
    var conn: Connection = undefined;
    conn.init(s, stream);
    defer conn.lingeringClose();
    conn.serve() catch |err| log.debug("connection ended: {t}", .{err});
}

const Connection = struct {
    server: *Server,
    stream: net.Stream,
    reader: net.Stream.Reader,
    writer: net.Stream.Writer,
    read_buf: [max_head_bytes]u8,
    write_buf: [1024]u8,

    const ReadError = error{ Timeout, EndOfStream, ReadFailed } || posix.PollError;

    /// Initializes in place: the reader and writer refer to buffers inside
    /// the connection, so it must not be moved afterwards.
    fn init(c: *Connection, s: *Server, stream: net.Stream) void {
        c.server = s;
        c.stream = stream;
        c.reader = stream.reader(s.io, &c.read_buf);
        c.writer = stream.writer(s.io, &c.write_buf);
    }

    fn respond(c: *Connection, r: http.Response) Io.Writer.Error!void {
        try r.write(&c.writer.interface);
    }

    /// Waits until the socket is readable or the idle timeout expires.
    fn waitReadable(c: *Connection) (error{Timeout} || posix.PollError)!void {
        var fds = [_]posix.pollfd{.{ .fd = c.stream.socket.handle, .events = posix.POLL.IN, .revents = 0 }};
        if (try posix.poll(&fds, read_timeout_ms) == 0) return error.Timeout;
    }

    /// Reads at least one more byte into the reader's buffer.
    fn fillMore(c: *Connection) ReadError!void {
        try c.waitReadable();
        try c.reader.interface.fillMore();
    }

    fn serve(c: *Connection) !void {
        const r = &c.reader.interface;
        const head_len = c.readHead() catch |err| switch (err) {
            error.HeadTooLarge => return c.respond(.{ .status = .request_header_fields_too_large }),
            error.NulInHead => return c.respond(.{ .status = .bad_request }),
            error.Timeout => {
                if (r.bufferedLen() > 0) try c.respond(.{ .status = .request_timeout });
                return err;
            },
            else => |e| return e,
        };

        switch (http.parseHead(r.buffered()[0..head_len])) {
            .reject => |status| try c.respond(.{ .status = status }),
            .request => |req| {
                r.toss(head_len + "\r\n\r\n".len);
                try c.route(req);
            },
        }
    }

    /// Buffers the request head; returns its length excluding the final
    /// CRLFCRLF, which is left in the buffer just after it.
    fn readHead(c: *Connection) (ReadError || error{ HeadTooLarge, NulInHead })!usize {
        const r = &c.reader.interface;
        var scanned: usize = 0;
        while (true) {
            const buf = r.buffered();
            // Resume the search a few bytes back so a terminator split across
            // reads is still found.
            const from = scanned -| 3;
            if (std.mem.indexOfPos(u8, buf, from, "\r\n\r\n")) |end| {
                if (std.mem.indexOfScalar(u8, buf[from..end], 0) != null) return error.NulInHead;
                return end;
            }
            if (std.mem.indexOfScalar(u8, buf[from..], 0) != null) return error.NulInHead;
            if (buf.len == max_head_bytes) return error.HeadTooLarge;
            scanned = buf.len;
            try c.fillMore();
        }
    }

    fn route(c: *Connection, req: http.Request) !void {
        const method = req.method;
        const target = req.target;

        if (std.mem.eql(u8, target, "/health")) {
            if (!std.mem.eql(u8, method, "GET")) return c.respond(.{ .status = .method_not_allowed, .allow = "GET" });
            return c.respond(.{ .status = .ok, .content_type = "text/plain; charset=utf-8", .body = "ok" });
        }

        if (std.mem.eql(u8, target, "/kv")) {
            if (!std.mem.eql(u8, method, "GET")) return c.respond(.{ .status = .method_not_allowed, .allow = "GET" });
            return c.handleList();
        }

        if (std.mem.startsWith(u8, target, "/kv/")) {
            const key = target["/kv/".len..];
            if (!isValidKey(key)) return c.respond(.{ .status = .bad_request });
            if (std.mem.eql(u8, method, "GET")) return c.handleGet(key);
            if (std.mem.eql(u8, method, "PUT")) return c.handlePut(key, req.content_length orelse 0);
            if (std.mem.eql(u8, method, "DELETE")) {
                const deleted = try c.server.store.delete(c.server.io, key);
                return c.respond(.{ .status = if (deleted) .no_content else .not_found });
            }
            return c.respond(.{ .status = .method_not_allowed, .allow = "GET, PUT, DELETE" });
        }

        return c.respond(.{ .status = .not_found });
    }

    fn handleList(c: *Connection) !void {
        var arena_state: std.heap.ArenaAllocator = .init(c.server.gpa);
        defer arena_state.deinit();
        const arena = arena_state.allocator();

        const keys = c.server.store.listKeys(c.server.io, arena) catch |err| switch (err) {
            error.OutOfMemory => return c.respond(.{ .status = .internal_server_error }),
            else => |e| return e,
        };
        const json = keysToJson(arena, keys) catch return c.respond(.{ .status = .internal_server_error });
        return c.respond(.{ .status = .ok, .content_type = "application/json", .body = json });
    }

    fn handleGet(c: *Connection, key: []const u8) !void {
        const gpa = c.server.gpa;
        const value = c.server.store.get(c.server.io, gpa, key) catch |err| switch (err) {
            error.OutOfMemory => return c.respond(.{ .status = .internal_server_error }),
            else => |e| return e,
        } orelse return c.respond(.{ .status = .not_found });
        defer gpa.free(value);
        return c.respond(.{ .status = .ok, .content_type = "application/octet-stream", .body = value });
    }

    fn handlePut(c: *Connection, request_key: []const u8, len: usize) !void {
        if (len > max_value_bytes) return c.respond(.{ .status = .payload_too_large });

        // The key points into the read buffer, which reading the body may
        // overwrite; keep a copy.
        var key_buf: [max_key_len]u8 = undefined;
        const key = key_buf[0..request_key.len];
        @memcpy(key, request_key);

        const gpa = c.server.gpa;
        const value = gpa.alloc(u8, len) catch return c.respond(.{ .status = .internal_server_error });
        errdefer gpa.free(value);
        try c.readBody(value);

        const result = c.server.store.put(c.server.io, key, value) catch |err| switch (err) {
            error.OutOfMemory => return c.respond(.{ .status = .internal_server_error }),
            else => |e| return e,
        };
        return c.respond(.{ .status = switch (result) {
            .created => .created,
            .replaced => .ok,
        } });
    }

    /// Fills `dest` with the request body, starting with any bytes that were
    /// received together with the head.
    fn readBody(c: *Connection, dest: []u8) ReadError!void {
        const r = &c.reader.interface;
        var filled = @min(r.bufferedLen(), dest.len);
        @memcpy(dest[0..filled], r.buffered()[0..filled]);
        r.toss(filled);

        while (filled < dest.len) {
            try c.waitReadable();
            // The reader's buffer is empty here, so this issues a single read
            // directly into `dest`.
            var bufs: [1][]u8 = .{dest[filled..]};
            filled += try r.readVec(&bufs);
        }
    }

    /// Half-closes the connection and drains whatever the peer still sends,
    /// so that closing does not reset the connection before the client has
    /// read the reply.
    fn lingeringClose(c: *Connection) void {
        const io = c.server.io;
        defer c.stream.close(io);
        c.stream.shutdown(io, .send) catch return;

        const r = &c.reader.interface;
        var drained: usize = 0;
        while (drained < drain_limit) {
            drained += r.bufferedLen();
            r.tossBuffered();
            c.fillMore() catch break;
        }
    }
};

fn isValidKey(key: []const u8) bool {
    if (key.len == 0 or key.len > max_key_len) return false;
    for (key) |ch| {
        if (!std.ascii.isAlphanumeric(ch) and ch != '_' and ch != '-') return false;
    }
    return true;
}

/// Renders keys as a JSON array of strings. Keys are restricted to
/// `[A-Za-z0-9_-]`, so no escaping is needed.
fn keysToJson(arena: Allocator, keys: []const []const u8) Allocator.Error![]const u8 {
    var len: usize = "[]".len;
    for (keys) |key| len += key.len + "\"\",".len;

    var out: std.ArrayList(u8) = try .initCapacity(arena, len);
    out.appendAssumeCapacity('[');
    for (keys, 0..) |key, i| {
        if (i > 0) out.appendAssumeCapacity(',');
        out.appendAssumeCapacity('"');
        out.appendSliceAssumeCapacity(key);
        out.appendAssumeCapacity('"');
    }
    out.appendAssumeCapacity(']');
    return out.items;
}

test isValidKey {
    try std.testing.expect(isValidKey("a"));
    try std.testing.expect(isValidKey("A-z_09"));
    try std.testing.expect(isValidKey("k" ** 64));
    try std.testing.expect(!isValidKey("k" ** 65));
    try std.testing.expect(!isValidKey(""));
    try std.testing.expect(!isValidKey("a/b"));
    try std.testing.expect(!isValidKey("bad.key"));
}

test keysToJson {
    var arena: std.heap.ArenaAllocator = .init(std.testing.allocator);
    defer arena.deinit();
    try std.testing.expectEqualStrings("[]", try keysToJson(arena.allocator(), &.{}));
    try std.testing.expectEqualStrings("[\"a\",\"b\"]", try keysToJson(arena.allocator(), &.{ "a", "b" }));
}

//! Thread-safe in-memory key-value store. Keys are byte strings, values are
//! arbitrary byte sequences. All memory is owned by the store's allocator.
const Store = @This();

const std = @import("std");
const Io = std.Io;
const Allocator = std.mem.Allocator;

gpa: Allocator,
lock: Io.RwLock = .init,
map: std.StringHashMapUnmanaged([]u8) = .empty,

pub const PutResult = enum { created, replaced };

pub fn init(gpa: Allocator) Store {
    return .{ .gpa = gpa };
}

pub fn deinit(s: *Store) void {
    var it = s.map.iterator();
    while (it.next()) |entry| {
        s.gpa.free(entry.key_ptr.*);
        s.gpa.free(entry.value_ptr.*);
    }
    s.map.deinit(s.gpa);
    s.* = undefined;
}

/// Stores `value` under `key`. On success the store takes ownership of
/// `value`, which must have been allocated with the store's allocator; on
/// error the caller keeps ownership.
pub fn put(s: *Store, io: Io, key: []const u8, value: []u8) (Allocator.Error || Io.Cancelable)!PutResult {
    try s.lock.lock(io);
    defer s.lock.unlock(io);

    const gop = try s.map.getOrPut(s.gpa, key);
    if (gop.found_existing) {
        s.gpa.free(gop.value_ptr.*);
        gop.value_ptr.* = value;
        return .replaced;
    }
    gop.key_ptr.* = s.gpa.dupe(u8, key) catch |err| {
        s.map.removeByPtr(gop.key_ptr);
        return err;
    };
    gop.value_ptr.* = value;
    return .created;
}

/// Returns a copy of the value stored under `key`, allocated with `gpa`, or
/// null when the key is absent.
pub fn get(s: *Store, io: Io, gpa: Allocator, key: []const u8) (Allocator.Error || Io.Cancelable)!?[]u8 {
    try s.lock.lockShared(io);
    defer s.lock.unlockShared(io);

    const value = s.map.get(key) orelse return null;
    return try gpa.dupe(u8, value);
}

/// Removes `key`; returns whether it was present.
pub fn delete(s: *Store, io: Io, key: []const u8) Io.Cancelable!bool {
    const removed = blk: {
        try s.lock.lock(io);
        defer s.lock.unlock(io);
        break :blk s.map.fetchRemove(key) orelse return false;
    };
    s.gpa.free(removed.key);
    s.gpa.free(removed.value);
    return true;
}

/// Returns a snapshot of every key, sorted ascending. The slice and the keys
/// are allocated with `arena`; free them by resetting the arena.
pub fn listKeys(s: *Store, io: Io, arena: Allocator) (Allocator.Error || Io.Cancelable)![]const []const u8 {
    const keys = blk: {
        try s.lock.lockShared(io);
        defer s.lock.unlockShared(io);

        const keys = try arena.alloc([]const u8, s.map.count());
        var it = s.map.keyIterator();
        var i: usize = 0;
        while (it.next()) |key| : (i += 1) keys[i] = try arena.dupe(u8, key.*);
        break :blk keys;
    };
    std.mem.sortUnstable([]const u8, keys, {}, lessThan);
    return keys;
}

fn lessThan(_: void, a: []const u8, b: []const u8) bool {
    return std.mem.order(u8, a, b) == .lt;
}

test "put, get, delete, list" {
    const io = std.testing.io;
    const gpa = std.testing.allocator;
    var s: Store = .init(gpa);
    defer s.deinit();

    try std.testing.expectEqual(.created, try s.put(io, "b", try gpa.dupe(u8, "1")));
    try std.testing.expectEqual(.replaced, try s.put(io, "b", try gpa.dupe(u8, "2")));
    try std.testing.expectEqual(.created, try s.put(io, "a", try gpa.dupe(u8, "")));

    const v = (try s.get(io, gpa, "b")).?;
    defer gpa.free(v);
    try std.testing.expectEqualStrings("2", v);
    try std.testing.expectEqual(null, try s.get(io, gpa, "zz"));

    var arena: std.heap.ArenaAllocator = .init(gpa);
    defer arena.deinit();
    const keys = try s.listKeys(io, arena.allocator());
    try std.testing.expectEqual(2, keys.len);
    try std.testing.expectEqualStrings("a", keys[0]);
    try std.testing.expectEqualStrings("b", keys[1]);

    try std.testing.expect(try s.delete(io, "a"));
    try std.testing.expect(!try s.delete(io, "a"));
}

//! Minimal HTTP/1.1 request-head parsing and response serialization.
const std = @import("std");
const Io = std.Io;
const Status = std.http.Status;

pub const Request = struct {
    method: []const u8,
    target: []const u8,
    content_length: ?usize = null,
};

/// The result of parsing a request head: either a request or the error
/// status to answer with.
pub const ParseResult = union(enum) {
    request: Request,
    reject: Status,
};

/// Parses a request head. `head` excludes the terminating CRLFCRLF. The
/// returned slices point into `head`.
pub fn parseHead(head: []const u8) ParseResult {
    const line_end = std.mem.indexOfScalar(u8, head, '\r') orelse head.len;
    const line = head[0..line_end];

    // Request line: method SP target SP version
    const sp1 = std.mem.indexOfScalar(u8, line, ' ') orelse return .{ .reject = .bad_request };
    if (sp1 == 0) return .{ .reject = .bad_request };
    const sp2 = std.mem.indexOfScalarPos(u8, line, sp1 + 1, ' ') orelse return .{ .reject = .bad_request };
    if (sp2 == sp1 + 1) return .{ .reject = .bad_request };

    const method = line[0..sp1];
    if (!isToken(method)) return .{ .reject = .bad_request };

    const version = line[sp2 + 1 ..];
    if (version.len != 8 or !std.mem.startsWith(u8, version, "HTTP/1.")) {
        return .{ .reject = if (std.mem.startsWith(u8, version, "HTTP/")) .http_version_not_supported else .bad_request };
    }

    var req: Request = .{ .method = method, .target = line[sp1 + 1 .. sp2] };
    var chunked = false;

    // Header fields, each preceded by CRLF.
    var pos = line_end;
    while (pos < head.len) {
        if (!std.mem.startsWith(u8, head[pos..], "\r\n")) return .{ .reject = .bad_request };
        pos += 2;
        const eol = std.mem.indexOfScalarPos(u8, head, pos, '\r') orelse head.len;
        const field = head[pos..eol];
        pos = eol;

        const colon = std.mem.indexOfScalar(u8, field, ':') orelse return .{ .reject = .bad_request };
        const name = field[0..colon];
        if (!isToken(name)) return .{ .reject = .bad_request };
        const value = std.mem.trim(u8, field[colon + 1 ..], " \t");

        if (std.ascii.eqlIgnoreCase(name, "Content-Length")) {
            const len = parseLength(value) orelse return .{ .reject = .bad_request };
            if (req.content_length) |prev| if (prev != len) return .{ .reject = .bad_request };
            req.content_length = len;
        } else if (std.ascii.eqlIgnoreCase(name, "Transfer-Encoding")) {
            chunked = true;
        }
    }

    if (chunked) return .{ .reject = if (req.content_length != null) .bad_request else .not_implemented };
    return .{ .request = req };
}

/// Parses a non-empty run of decimal digits, rejecting signs and overflow.
fn parseLength(s: []const u8) ?usize {
    if (s.len == 0) return null;
    for (s) |c| if (!std.ascii.isDigit(c)) return null;
    return std.fmt.parseUnsigned(usize, s, 10) catch null;
}

/// Whether `s` is a non-empty RFC 9110 token.
fn isToken(s: []const u8) bool {
    if (s.len == 0) return false;
    for (s) |c| {
        if (!std.ascii.isAlphanumeric(c) and std.mem.indexOfScalar(u8, "!#$%&'*+-.^_`|~", c) == null) return false;
    }
    return true;
}

pub const Response = struct {
    status: Status,
    content_type: ?[]const u8 = null,
    /// Value of the `Allow` header; set on 405 responses.
    allow: ?[]const u8 = null,
    body: []const u8 = "",

    pub fn write(r: Response, w: *Io.Writer) Io.Writer.Error!void {
        try w.print("HTTP/1.1 {d} {s}\r\nContent-Length: {d}\r\nConnection: close\r\n", .{
            @intFromEnum(r.status), r.status.phrase() orelse "Unknown", r.body.len,
        });
        if (r.content_type) |ct| try w.print("Content-Type: {s}\r\n", .{ct});
        if (r.allow) |allow| try w.print("Allow: {s}\r\n", .{allow});
        try w.writeAll("\r\n");
        try w.writeAll(r.body);
        try w.flush();
    }
};

fn expectReject(status: Status, head: []const u8) !void {
    try std.testing.expectEqual(ParseResult{ .reject = status }, parseHead(head));
}

test parseHead {
    const ok = parseHead("PUT /kv/a HTTP/1.1\r\nHost: x\r\ncontent-length:  5 \r\nConnection: close");
    try std.testing.expectEqualStrings("PUT", ok.request.method);
    try std.testing.expectEqualStrings("/kv/a", ok.request.target);
    try std.testing.expectEqual(5, ok.request.content_length.?);

    try std.testing.expectEqual(null, parseHead("GET / HTTP/1.0").request.content_length);
    try expectReject(.bad_request, "GET /");
    try expectReject(.bad_request, " / HTTP/1.1");
    try expectReject(.bad_request, "GET  HTTP/1.1");
    try expectReject(.bad_request, "G@T / HTTP/1.1");
    try expectReject(.http_version_not_supported, "GET / HTTP/2.0");
    try expectReject(.bad_request, "GET / FTP/1.1");
    try expectReject(.bad_request, "GET / HTTP/1.1\r\nNoColon");
    try expectReject(.bad_request, "GET / HTTP/1.1\r\n: empty");
    try expectReject(.bad_request, "GET / HTTP/1.1\r\nContent-Length: -1");
    try expectReject(.bad_request, "GET / HTTP/1.1\r\nContent-Length: 99999999999999999999999");
    try expectReject(.bad_request, "GET / HTTP/1.1\r\nContent-Length: 1\r\nContent-Length: 2");
    try expectReject(.not_implemented, "GET / HTTP/1.1\r\nTransfer-Encoding: chunked");
    try expectReject(.bad_request, "GET / HTTP/1.1\r\nTransfer-Encoding: chunked\r\nContent-Length: 1");
}

//! kvhttp: a minimal HTTP/1.1 in-memory key-value server.
//!
//! Usage: app <port>. Listens on 127.0.0.1:<port> and serves until killed.
const std = @import("std");
const Io = std.Io;

const Server = @import("Server.zig");
const Store = @import("Store.zig");

pub const std_options: std.Options = .{
    // Every worker thread of the I/O pool lives for the whole process. Only
    // give each one an alternate signal stack when the segfault handler that
    // uses it is enabled; otherwise it is dead weight per thread.
    .signal_stack_size = if (std.debug.default_enable_segfault_handler) (std.Options{}).signal_stack_size else null,
};

pub fn main(init: std.process.Init) !u8 {
    const io = init.io;

    var args = init.minimal.args.iterate();
    const argv0 = args.next() orelse "app";
    const port_arg = args.next() orelse return usage(argv0);
    if (args.next() != null) return usage(argv0);

    const port = std.fmt.parseInt(u16, port_arg, 10) catch 0;
    if (port == 0) {
        std.log.err("invalid port: {s}", .{port_arg});
        return 2;
    }

    var store: Store = .init(init.gpa);
    defer store.deinit();

    const address: Io.net.IpAddress = .{ .ip4 = .loopback(port) };
    var listener = address.listen(io, .{
        .reuse_address = true,
        .kernel_backlog = std.math.maxInt(u16),
    }) catch |err| {
        std.log.err("listen on {f}: {t}", .{ address, err });
        return 1;
    };
    defer listener.deinit(io);

    var server: Server = .{ .io = io, .gpa = init.gpa, .store = &store };
    server.run(&listener) catch |err| {
        std.log.err("accept: {t}", .{err});
        return 1;
    };
    return 0;
}

fn usage(argv0: []const u8) u8 {
    std.log.err("usage: {s} <port>", .{argv0});
    return 2;
}

